import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as d,ag as r}from"./chunks/mermaid.Bf0DxEx6.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"T3 Code 学习地图","description":"T3 Code 是 T3 Tools, Inc. 开源的「coding agent 控制面」：自己不带模型，驱动你电脑上已装好的 Claude Code、Codex 等 agent，并支持人离开电脑后从手机继续。本页给出产品家族表、选型决策，以及本目录三页的读法。","frontmatter":{"title":"T3 Code 学习地图","description":"T3 Code 是 T3 Tools, Inc. 开源的「coding agent 控制面」：自己不带模型，驱动你电脑上已装好的 Claude Code、Codex 等 agent，并支持人离开电脑后从手机继续。本页给出产品家族表、选型决策，以及本目录三页的读法。","domain":"product","tags":["coding-agent","agent-workspace","remote-access"],"role":"map"},"headers":[],"relativePath":"zh/products/t3code/index.md","filePath":"zh/products/t3code/index.md","lastUpdated":1795592559000}'),o={name:"zh/products/t3code/index.md"};function l(n,t,c,s,i,h){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="t3-code-学习地图" tabindex="-1">T3 Code 学习地图 <a class="header-anchor" href="#t3-code-学习地图" aria-label="Permalink to &quot;T3 Code 学习地图&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> T3 Code 是一个开源的本地应用，官方定位是 <strong>The open-source control plane for coding agents</strong>。它不提供模型，也不替代你的订阅；它驱动你电脑上已经装好的 coding agent，把它们放进同一个界面、同一套审批，并让你离开电脑后从手机继续。</p><p>这一组页面回答四件事：它是什么，怎么装上并跑通，日常怎么用，内部怎么运作。</p></blockquote><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>官方名称</td><td>T3 Code</td></tr><tr><td>公司</td><td>T3 Tools, Inc.（官网页脚、README 和 App Store 开发者栏的写法）</td></tr><tr><td>GitHub 组织与仓库</td><td><code>pingdotgg</code>，仓库 <a href="https://github.com/pingdotgg/t3code" target="_blank" rel="noreferrer"><code>pingdotgg/t3code</code></a></td></tr><tr><td>许可</td><td>源代码 MIT。名字、标志和品牌不在 MIT 范围内</td></tr><tr><td>官网与下载</td><td><a href="https://t3.codes" target="_blank" rel="noreferrer">t3.codes</a>、<a href="https://t3.codes/download" target="_blank" rel="noreferrer">t3.codes/download</a></td></tr><tr><td>命令行包名</td><td><code>t3</code>，例如 <code>npx t3@latest</code>；仓库内部的包用 <code>@t3tools</code> 作用域</td></tr><tr><td>最早可见的发布记录</td><td><code>v0.0.0-alpha.3</code>，发布于 2026-03-02（<a href="https://github.com/pingdotgg/t3code/releases/tag/v0.0.0-alpha.3" target="_blank" rel="noreferrer">GitHub Releases</a>，截至 2026-11-24）</td></tr><tr><td>文档位置</td><td>放在 GitHub 仓库里：<code>docs/user/</code> 讲使用，<code>docs/internals/</code> 讲内部设计</td></tr></tbody></table><p>本页核对时，t3.codes 的页脚只有 GitHub、Discord、Download、iOS app、Android app、Terms、Privacy、Security 这些入口，没有看到独立的文档站。</p><h2 id="写给谁-先决条件-非目标" tabindex="-1">写给谁 / 先决条件 / 非目标 <a class="header-anchor" href="#写给谁-先决条件-非目标" aria-label="Permalink to &quot;写给谁 / 先决条件 / 非目标&quot;">​</a></h2><ul><li><strong>写给谁</strong>：手上已有两个以上 coding agent 的前端或 AI 应用开发者，尤其是没接触过「agent 工作区」这类产品的人。</li><li><strong>先决条件</strong>：一台你控制的电脑（macOS、Windows 10 / 11、Linux）；至少一个已安装并登录的 agent，比如 Claude Code 或 Codex。</li><li><strong>非目标</strong>： <ul><li>不教 Claude Code 和 Codex 本身，去 <a href="./../claude/">Claude Code</a> 和 <a href="./../codex/">Codex</a>。</li><li>不教本地跑模型。官方 FAQ 写明 T3 Code 不支持本地模型。</li><li>不讲 Tailscale 怎么搭，去 <a href="./../tailscale/">Tailscale</a>。</li><li>不展开 T3 Chat 这个另一款产品。</li></ul></li></ul><h2 id="产品家族" tabindex="-1">产品家族 <a class="header-anchor" href="#产品家族" aria-label="Permalink to &quot;产品家族&quot;">​</a></h2><p>官方名称抄自官方页面和仓库文档。本目录只有三页，所以多数家族成员落在教程的某一节里。</p><table tabindex="0"><thead><tr><th>官方名称</th><th>官方 URL</th><th>本站去向</th></tr></thead><tbody><tr><td><strong>Desktop app</strong>（桌面应用，macOS / Windows / Linux）</td><td><a href="https://t3.codes/download" target="_blank" rel="noreferrer">t3.codes/download</a></td><td>独立页：<a href="./t3code.html">教程</a> 第六、七节</td></tr><tr><td><strong><code>t3</code> command</strong>（命令行）</td><td>下载页的 Terminal 区块，<a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/install.md" target="_blank" rel="noreferrer">Install 文档</a></td><td>独立页：<a href="./t3code.html">教程</a> 第六节</td></tr><tr><td><strong>Web</strong>（托管网页应用）</td><td><a href="https://app.t3.codes" target="_blank" rel="noreferrer">app.t3.codes</a></td><td>独立页：<a href="./t3code.html">教程</a> 第八节第 2 小节</td></tr><tr><td><strong>Mobile app</strong>（iOS 与 Android）</td><td><a href="https://apps.apple.com/us/app/t3-code-remote-claude-more/id6787819824" target="_blank" rel="noreferrer">App Store</a>、<a href="https://play.google.com/store/apps/details?id=com.t3tools.t3code" target="_blank" rel="noreferrer">Google Play</a></td><td>独立页：<a href="./t3code.html">教程</a> 第六节第 4 步、第八节第 2 小节</td></tr><tr><td><strong>Background service</strong>（后台服务）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/background-service.md" target="_blank" rel="noreferrer">Running in the background</a></td><td>独立页：<a href="./t3code.html">教程</a> 第八节第 7 小节</td></tr><tr><td><strong>T3 Connect</strong>（含 relay 中继）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/remote-access.md" target="_blank" rel="noreferrer">Remote access</a>、<a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/internals/06_t3-connect.md" target="_blank" rel="noreferrer">T3 Connect 设计说明</a></td><td>独立页：<a href="./t3code.html">教程</a> 与 <a href="./source.html">源码解读</a></td></tr><tr><td><strong>Guest links</strong>（访客链接，beta）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/guest-links.md" target="_blank" rel="noreferrer">Guest links</a></td><td>独立页：<a href="./t3code.html">教程</a> 第十一节</td></tr><tr><td><strong>Managed policy</strong>（托管策略）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/managed-policy.md" target="_blank" rel="noreferrer">Managed policy</a></td><td>独立页：<a href="./t3code.html">教程</a> 第十一节</td></tr><tr><td><strong>Outside agents</strong>（T3 Code 的 MCP 服务器）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/outside-agents.md" target="_blank" rel="noreferrer">Outside agents</a></td><td>地图一行：让你终端里的 Claude Code、Codex 或 ChatGPT 反过来驱动 T3 Code 的线程</td></tr><tr><td><strong>ACP Registry agents</strong></td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/providers-acp.md" target="_blank" rel="noreferrer">ACP providers</a></td><td>地图一行：概念见<a href="./t3code.html">教程</a>第三节，添加步骤见官方页</td></tr><tr><td><strong>Workflows</strong>（早期功能，在 Labs 里）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/workflows.md" target="_blank" rel="noreferrer">Workflows</a></td><td>地图一行：用 TypeScript 把 agent、定时和人工确认串成一次可恢复的运行</td></tr><tr><td><strong>Device panel</strong>（模拟器面板）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/devices.md" target="_blank" rel="noreferrer">Devices</a></td><td>地图一行：在线程旁边看 iOS 模拟器或 Android 模拟器</td></tr><tr><td><strong>Triage</strong>（分诊）</td><td><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/triage.md" target="_blank" rel="noreferrer">Triage an issue</a></td><td>地图一行：它是什么见<a href="./t3code.html">教程</a>第三节</td></tr><tr><td><strong>T3 Chat</strong>（另一个产品）</td><td>见 <a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/faq.md" target="_blank" rel="noreferrer">FAQ</a></td><td>地图一行：本页核对到的用途是关联账号后提高 T3 Connect 的机器上限</td></tr></tbody></table><h3 id="容易撞名" tabindex="-1">容易撞名 <a class="header-anchor" href="#容易撞名" aria-label="Permalink to &quot;容易撞名&quot;">​</a></h3><ul><li><strong>T3 Code 不是 T3 Chat。</strong> 后者是 T3 的另一款产品。本页在 T3 Code 的文档里核对到它的一个用途：关联付费的 T3 Chat 账号后，T3 Connect 能链接的机器更多。</li><li><strong>T3 Code 不是 Claude Code，也不是 Codex。</strong> 它是驱动方，那两个是被驱动的 agent。官方 FAQ 的原话是：T3 Code uses those harnesses. It is not a harness, and it does not work without one.</li><li><strong>T3 Tools, Inc. 与 <code>pingdotgg</code>。</strong> 前者是官方页面上写的公司名，后者是它的 GitHub 组织名。</li><li><strong>T3 Connect 不是 Tailscale。</strong> 前者是 T3 自家的远程连接方案；后者是第三方网络，T3 Code 把它当作另一条可选的连接路线。</li><li><strong><code>t3</code> 命令和桌面应用不是两个产品。</strong> 它们是同一个服务器的两种启动方式，桌面应用里也自带 <code>t3</code>。</li><li><strong>名字不在开源许可里。</strong> MIT 只覆盖源代码。官方要求公开的 fork 换掉 T3 Code 的名字和图标，并声明与官方无关。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><h3 id="没有它和有它" tabindex="-1">没有它和有它 <a class="header-anchor" href="#没有它和有它" aria-label="Permalink to &quot;没有它和有它&quot;">​</a></h3><p>左栏是很多读者的处境，本页把它当作前提，不去断言某款产品的细节。</p><table tabindex="0"><thead><tr><th>事情</th><th>各开各的终端或应用</th><th>用 T3 Code</th></tr></thead><tbody><tr><td>同时用两个 agent</td><td>两个窗口，各自的界面</td><td>同一个界面里切换。README：Every agent in one place</td></tr><tr><td>任务中途想换模型</td><td>上下文要自己搬</td><td>在同一线程里换 provider，T3 Code 按预算带过去对话上下文</td></tr><tr><td>并行跑几个任务</td><td>自己开终端、自己管分支</td><td>一条线程一个 worktree，各有分支和工作目录</td></tr><tr><td>看改了什么、提交</td><td>各有各的做法</td><td>统一的 diff 面板和 Git 操作</td></tr><tr><td>人离开电脑</td><td>回到电脑前才能点批准</td><td>手机批准、收通知</td></tr><tr><td>agent 进程崩了</td><td>看各工具自己的恢复能力</td><td>线程记录持久保存，官方术语表写明它不随 provider 进程退出而消失</td></tr></tbody></table><h3 id="与替代方案" tabindex="-1">与替代方案 <a class="header-anchor" href="#与替代方案" aria-label="Permalink to &quot;与替代方案&quot;">​</a></h3><p>只写能核实的内容。涉及别家产品的部分，链接到本站各自的页面。</p><table tabindex="0"><thead><tr><th>方案</th><th>它是什么</th><th>依据</th></tr></thead><tbody><tr><td>各 agent 自带的界面</td><td>Claude Code、Codex 各有自己的终端和桌面应用</td><td>本站：<a href="./../claude/">Claude Code</a>、<a href="./../codex/">Codex</a></td></tr><tr><td><strong>T3 Code</strong></td><td>跨厂商的驱动方，自带订阅，驱动已装好的 agent</td><td>README、FAQ</td></tr><tr><td>Codex desktop app、Conductor、Claude Desktop、Cursor Glass</td><td>T3 Code 官方点名「启发过它」的四款产品，官方说它们都没达到自己的标准</td><td>FAQ：Why use T3 Code instead of Claude Code or the Codex app?</td></tr><tr><td><a href="./../cindy/">Cindy</a></td><td>同类的多 agent 工作区产品</td><td>对比见 Cindy 页；本页没有核实它的细节</td></tr><tr><td><a href="./../tailscale/">Tailscale</a></td><td>一条连接路线，解决「怎么连回你的电脑」，不驱动 agent</td><td>T3 Code 的 Remote access 文档把它列为 T3 Connect 之外的选项</td></tr></tbody></table><h2 id="快速决策-我该用哪个" tabindex="-1">快速决策：我该用哪个 <a class="header-anchor" href="#快速决策-我该用哪个" aria-label="Permalink to &quot;快速决策：我该用哪个&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我的情况</th><th>用什么</th></tr></thead><tbody><tr><td>只用一个 agent，偶尔用</td><td>先用它自带的界面：<a href="./../claude/">Claude Code</a> 或 <a href="./../codex/">Codex</a></td></tr><tr><td>同时用两个以上 agent，想在一个窗口里切</td><td>T3 Code 桌面应用</td></tr><tr><td>想并行跑多个任务，各占一个分支</td><td>T3 Code，开线程时选 <strong>New worktree</strong></td></tr><tr><td>人常不在电脑前，要用手机点批准</td><td>T3 Code 加 T3 Connect，加手机 App</td></tr><tr><td>公司网络挡了 T3 Connect 的出站端口</td><td>T3 Code 加局域网直连，或 <a href="./../tailscale/">Tailscale</a></td></tr><tr><td>想在自己的服务器上跑，平时远程连</td><td>用 <code>t3 up</code> 装成后台服务，再用 <a href="https://app.t3.codes" target="_blank" rel="noreferrer">app.t3.codes</a> 或手机连</td></tr><tr><td>不想经过 T3 的任何服务</td><td>不开 T3 Connect，只用局域网或 Tailscale 直连，并关掉遥测</td></tr><tr><td>要给团队的机器定权限上限</td><td>T3 Code 的托管策略</td></tr><tr><td>想和同类产品比一比</td><td><a href="./../cindy/">Cindy</a></td></tr></tbody></table><h2 id="本目录怎么读" tabindex="-1">本目录怎么读 <a class="header-anchor" href="#本目录怎么读" aria-label="Permalink to &quot;本目录怎么读&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>读完能做什么</th><th>什么时候读</th></tr></thead><tbody><tr><td><a href="./t3code.html">教程</a></td><td>装好它、跑通第一个线程、按场景选权限模式、从手机继续、说出三条安全边界</td><td>第一次用</td></tr><tr><td><a href="./source.html">源码解读</a></td><td>看懂一条线程的数据流、权限模式在哪段代码里被执行、T3 Connect 的信任模型</td><td>用顺之后，或者准备给 T3 Code 提 PR</td></tr></tbody></table><p>建议顺序：</p><ol><li><strong>先读<a href="./t3code.html">教程</a>。</strong> 10 分钟的纵向切片在第七节，装好就能跑。概念看不懂时回到第三节。</li><li><strong>再读<a href="./source.html">源码解读</a>。</strong> 它默认你已经会开线程、切权限模式，不然「命令」「事件」「副作用」这些词没有落点。</li><li><strong>回头看本页的家族表。</strong> 教程只展开了家族里最常用的几项，访客链接、托管策略、MCP 服务器这些按需再查。</li></ol><h2 id="官方资源-深入阅读" tabindex="-1">官方资源（深入阅读） <a class="header-anchor" href="#官方资源-深入阅读" aria-label="Permalink to &quot;官方资源（深入阅读）&quot;">​</a></h2><p>仓库里的文档链接固定在提交 <code>d00aaac8</code>，想读最新版把提交号换成 <code>main</code>。</p><ul><li><a href="https://t3.codes" target="_blank" rel="noreferrer">官网 t3.codes</a>：定位、下载入口，以及一句它支持的 agent 列表。</li><li><a href="https://t3.codes/download" target="_blank" rel="noreferrer">下载页</a>：三个桌面平台的安装包、命令行安装方式、手机商店入口。</li><li><a href="https://app.t3.codes" target="_blank" rel="noreferrer">app.t3.codes</a>：托管网页应用，只负责连到你自己的环境。</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/README.md" target="_blank" rel="noreferrer">仓库 README</a>：它是什么、支持哪些 agent、怎么装、许可与品牌政策。</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/README.md" target="_blank" rel="noreferrer">docs/README.md</a>：全部文档的目录，分使用、内部设计、运维手册三块。</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/install.md" target="_blank" rel="noreferrer">Install T3 Code</a>：各平台安装与每个 provider 的登录方式。</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/user/faq.md" target="_blank" rel="noreferrer">FAQ</a>：成本、额度、远程、封号，以及「T3 Code 是不是 harness」。</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/docs/internals/01_architecture.md" target="_blank" rel="noreferrer">Architecture</a>：所有权边界、「先落库再执行副作用」的设计约束。</li><li><a href="https://github.com/pingdotgg/t3code/blob/d00aaac85fc71195f133a8580c3f0f2e29ac33a2/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>：谁被信任、什么算漏洞、什么是有意为之。</li><li><a href="https://github.com/pingdotgg/t3code/releases" target="_blank" rel="noreferrer">GitHub Releases</a>：稳定版和 nightly 的变更记录。</li><li><a href="https://github.com/pingdotgg/t3code/discussions/categories/ideas" target="_blank" rel="noreferrer">Discussions 里的 Ideas</a>：提功能建议的地方。README 写明功能要先有被接受的讨论。</li><li><a href="https://discord.gg/jn4EGJjrvv" target="_blank" rel="noreferrer">Discord</a>：README 给出的求助渠道，邀请页显示的服务器是 Theo&#39;s Typesafe Cult。</li><li><a href="https://t3.gg/blog/post/what-is-a-harness" target="_blank" rel="noreferrer">What is a &quot;harness&quot;?</a>：官方博客，讲模型、harness、agent 和 T3 Code 的分工。</li><li><a href="https://agentclientprotocol.com/overview/introduction" target="_blank" rel="noreferrer">Agent Client Protocol</a>：ACP 的官方介绍。</li></ul><h2 id="相关页面-站内" tabindex="-1">相关页面（站内） <a class="header-anchor" href="#相关页面-站内" aria-label="Permalink to &quot;相关页面（站内）&quot;">​</a></h2><ul><li><a href="./t3code.html">教程</a>、<a href="./source.html">源码解读</a>：本目录的另外两页。</li><li><a href="./../claude/">Claude Code</a>、<a href="./../codex/">Codex</a>：被 T3 Code 驱动的两个 agent 本身。</li><li><a href="./../codex/dot.html">Codex Dot</a>：OpenAI 侧的常驻智能体，想比较「谁来接着推进任务」时对照着看。</li><li><a href="./../cindy/">Cindy</a>：同类的多 agent 工作区产品。</li><li><a href="./../tailscale/">Tailscale</a>：T3 Connect 之外的连接路线。</li><li><a href="./../uu-remote/">UU Remote</a>：「人不在电脑前」的另一类做法，先弄清自己要的是哪一种。</li></ul>',30)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
